    return String(r).trim();
}
function siFmt(v,unit){
    if(!isFinite(v))return v+" "+unit;
    var a=Math.abs(v),sg=v<0?"-":"";
    var P=[[1e3,"k"],[1,""],[1e-3,"m"],[1e-6,"\u00b5"],[1e-9,"n"]];
    if(a===0)return"0 "+unit;
    for(var i=0;i<P.length;i++){if(a>=P[i][0]*0.9999)return sg+parseFloat((a/P[i][0]).toPrecision(4))+" "+P[i][1]+unit;}
    return sg+a.toExponential(3)+" "+unit;
}
async function resetAndAcquire(){
    try{connection.release();}catch(e){}
    await new Promise(r=>setTimeout(r,400));
    await connection.acquire(true);
}

// ── EA-PS2342 Configure ───────────────────────────────────────────────────────
await resetAndAcquire();
try {
    var nomV = 42.0, nomI = 6.0;
    try {
        var info = JSON.parse(qts(await connection.query("INFO?")));
        nomV = parseFloat(info.nom_voltage)||42.0;
        nomI = parseFloat(info.nom_current)||6.0;
    } catch(ie) {}
    var maxOvp = parseFloat((nomV*1.1).toFixed(2));
    var maxOcp = parseFloat((nomI*1.1).toFixed(2));

    // Pre-fill from cache then overwrite with live device values
    var cached = storage.getItem('ea_config', null);
    var def1 = cached ? cached.ch1
             : {output:"OFF",v:0,i:0,ovp:maxOvp,ocp:maxOcp,set_ovp:false,set_ocp:false};
    var def2 = cached ? cached.ch2
             : {output:"OFF",v:0,i:0,ovp:maxOvp,ocp:maxOcp,set_ovp:false,set_ocp:false};
    var defTracking = cached ? (cached.tracking||false) : false;

    try {
        var s1 = qts(await connection.query("SETP? 1")).split(",");
        var s2 = qts(await connection.query("SETP? 2")).split(",");
        // SETP? now returns: v_set,i_set,on,tracking
        if (s1.length >= 3) {
            def1.v = parseFloat(s1[0])||0;
            def1.i = parseFloat(s1[1])||0;
            def1.output = s1[2]==="1"?"ON":"OFF";
        }
        if (s2.length >= 3) {
            def2.v = parseFloat(s2[0])||0;
            def2.i = parseFloat(s2[1])||0;
            def2.output = s2[2]==="1"?"ON":"OFF";
        }
        // Tracking state from SETP? field 4 or direct TRACK? query
        var trk = qts(await connection.query("TRACK?"));
        defTracking = (trk==="1");

        var ovp1r = parseFloat(qts(await connection.query("OVP? 1"))||String(maxOvp));
        var ocp1r = parseFloat(qts(await connection.query("OCP? 1"))||String(maxOcp));
        var ovp2r = parseFloat(qts(await connection.query("OVP? 2"))||String(maxOvp));
        var ocp2r = parseFloat(qts(await connection.query("OCP? 2"))||String(maxOcp));
        def1.ovp = ovp1r; def1.ocp = ocp1r;
        def2.ovp = ovp2r; def2.ocp = ocp2r;
    } catch(re) {}

    var vals = await input({
        title: "EA-PS2342  —  Configure  ["+nomV.toFixed(0)+"V / "+nomI.toFixed(0)+"A]",
        size: "small",
        fields: [
            // ── Tracking ─────────────────────────────────────────────────
            // Shown at the top — affects visibility of CH2 fields below
            { name:"tracking", displayName:"Tracking  (CH2 \u2192 mirrors CH1)",
              type:"boolean", checkboxStyleSwitch:true },

            // ── CH1 ──────────────────────────────────────────────────────
            { name:"ch1_output", displayName:"CH1  Output",
              type:"enum",
              enumItems:[{id:"ON",label:"On"},{id:"OFF",label:"Off"}] },
            { name:"ch1_v", displayName:"CH1  Voltage (V)",
              type:"number", minValue:0, maxValue:nomV },
            { name:"ch1_i", displayName:"CH1  Current Limit (A)",
              type:"number", minValue:0, maxValue:nomI },
            { name:"ch1_set_ovp", displayName:"CH1  OVP",
              type:"boolean", checkboxStyleSwitch:true },
            { name:"ch1_ovp", displayName:"CH1  OVP (V)",
              type:"number", minValue:0, maxValue:maxOvp,
              visible:function(v){return v.ch1_set_ovp;} },
            { name:"ch1_set_ocp", displayName:"CH1  OCP",
              type:"boolean", checkboxStyleSwitch:true },
            { name:"ch1_ocp", displayName:"CH1  OCP (A)",
              type:"number", minValue:0, maxValue:maxOcp,
              visible:function(v){return v.ch1_set_ocp;} },

            // ── CH2 — hidden when tracking is on ─────────────────────────
            { name:"ch2_output", displayName:"CH2  Output",
              type:"enum",
              enumItems:[{id:"ON",label:"On"},{id:"OFF",label:"Off"}],
              enclosureClassName:"eez-studio-top-divider",
              visible:function(v){return !v.tracking;} },
            { name:"ch2_v", displayName:"CH2  Voltage (V)",
              type:"number", minValue:0, maxValue:nomV,
              visible:function(v){return !v.tracking;} },
            { name:"ch2_i", displayName:"CH2  Current Limit (A)",
              type:"number", minValue:0, maxValue:nomI,
              visible:function(v){return !v.tracking;} },
            { name:"ch2_set_ovp", displayName:"CH2  OVP",
              type:"boolean", checkboxStyleSwitch:true,
              visible:function(v){return !v.tracking;} },
            { name:"ch2_ovp", displayName:"CH2  OVP (V)",
              type:"number", minValue:0, maxValue:maxOvp,
              visible:function(v){return !v.tracking && v.ch2_set_ovp;} },
            { name:"ch2_set_ocp", displayName:"CH2  OCP",
              type:"boolean", checkboxStyleSwitch:true,
              visible:function(v){return !v.tracking;} },
            { name:"ch2_ocp", displayName:"CH2  OCP (A)",
              type:"number", minValue:0, maxValue:maxOcp,
              visible:function(v){return !v.tracking && v.ch2_set_ocp;} },

            // ── Tracking active note ──────────────────────────────────────
            // Shown only when tracking is on, explains why CH2 is hidden
            { name:"_trk_note", displayName:"CH2 follows CH1 automatically",
              type:"boolean",
              visible:function(v){return v.tracking;},
              checkboxStyleSwitch:false }
        ]
    }, {
        tracking:defTracking,
        ch1_output:def1.output, ch1_v:def1.v, ch1_i:def1.i,
        ch1_set_ovp:def1.set_ovp||false, ch1_ovp:def1.ovp,
        ch1_set_ocp:def1.set_ocp||false, ch1_ocp:def1.ocp,
        ch2_output:def2.output, ch2_v:def2.v, ch2_i:def2.i,
        ch2_set_ovp:def2.set_ovp||false, ch2_ovp:def2.ovp,
        ch2_set_ocp:def2.set_ocp||false, ch2_ocp:def2.ocp,
        _trk_note:false
    });

    if (!vals) { notify.info("Cancelled"); connection.release(); return; }

    // Apply each setting using query() so EEZ waits for the bridge acknowledgement
    // before sending the next command. connection.command() is fire-and-forget —
    // all commands would arrive at the bridge simultaneously, causing the device
    // to receive telegrams before it has finished processing the previous one.

    // Tracking — wait for full acknowledgement before CH1/CH2 commands
    var rTrk = qts(await connection.query("TRACK "+(vals.tracking?"ON":"OFF")));
    if (rTrk.indexOf("ERR")===0) { notify.error("TRACK failed: "+rTrk); connection.release(); return; }
    // Extra settle time after tracking state change
    await new Promise(r=>setTimeout(r,300));

    // CH1 — 0V guard: cannot enable output with 0V setpoint
    var ch1_safe_out = (vals.ch1_output==="ON" && vals.ch1_v===0) ? "OFF" : vals.ch1_output;
    var rC1 = qts(await connection.query("CONF:OUTP 1,"+vals.ch1_v+","+vals.ch1_i+","+ch1_safe_out));
    if (rC1.indexOf("ERR")===0) { notify.error("CH1 configure failed: "+rC1); connection.release(); return; }
    if (vals.ch1_set_ovp) await connection.query("OVP 1,"+vals.ch1_ovp);
    if (vals.ch1_set_ocp) await connection.query("OCP 1,"+vals.ch1_ocp);

    // CH2 — only when tracking is off
    if (!vals.tracking) {
        var ch2_safe_out = (vals.ch2_output==="ON" && vals.ch2_v===0) ? "OFF" : vals.ch2_output;
        var rC2 = qts(await connection.query("CONF:OUTP 2,"+vals.ch2_v+","+vals.ch2_i+","+ch2_safe_out));
        if (rC2.indexOf("ERR")===0) { notify.error("CH2 configure failed: "+rC2); connection.release(); return; }
        if (vals.ch2_set_ovp) await connection.query("OVP 2,"+vals.ch2_ovp);
        if (vals.ch2_set_ocp) await connection.query("OCP 2,"+vals.ch2_ocp);
    }

    // Brief settle before readback
    await new Promise(r=>setTimeout(r,200));
    var a1=qts(await connection.query("MEAS:ALL? 1")).split(",");
    var a2=qts(await connection.query("MEAS:ALL? 2")).split(",");
    // MEAS:ALL? now returns v,i,on,mode,tracking

    storage.setItem('ea_config', {
        tracking: vals.tracking,
        ch1:{output:vals.ch1_output,v:vals.ch1_v,i:vals.ch1_i,
             ovp:vals.ch1_ovp,ocp:vals.ch1_ocp,
             set_ovp:vals.ch1_set_ovp,set_ocp:vals.ch1_set_ocp},
        ch2:{output:vals.ch2_output,v:vals.ch2_v,i:vals.ch2_i,
             ovp:vals.ch2_ovp,ocp:vals.ch2_ocp,
             set_ovp:vals.ch2_set_ovp,set_ocp:vals.ch2_set_ocp}
    });

    function fmtAct(a, n) {
        if (a.length < 4) return "CH"+n+": ERR";
        var trk = a[4]==="1" ? " TRK" : "";
        return "CH"+n+": "+parseFloat(a[0]).toFixed(3)+"V  "
            +parseFloat(a[1]).toFixed(4)+"A  "+(a[2]==="1"?"ON":"OFF")+" "+a[3]+trk;
    }
    var warnings = [];
    if (vals.ch1_output==="ON" && vals.ch1_v===0)
        warnings.push("CH1 output left OFF (0V setpoint)");
    if (!vals.tracking && vals.ch2_output==="ON" && vals.ch2_v===0)
        warnings.push("CH2 output left OFF (0V setpoint)");
    var trkMsg = vals.tracking ? "  [TRACKING ON]" : "";
    notify.info(fmtAct(a1,1)+"    "+fmtAct(a2,2)+trkMsg);
    if (warnings.length > 0) notify.info("⚠ "+warnings.join("  |  "));

} catch(e) {
    notify.error("Configure failed: "+e.message);
} finally {
    connection.release();
}

