// ── EA-PS2342 Live Readout ────────────────────────────────────────────────────
// MEAS:ALL? returns: v,i,on,mode,tracking
// TO STOP: open the Scripts panel (scroll icon in left sidebar) → Stop button.
const MAX_READS = 9999;

await resetAndAcquire();
var hint = notify.info(
    "\u25b6 Live running  \u2502  TO STOP: click the \uD83D\uDCC4 Scripts icon in the left sidebar \u2192 Stop",
    { autoClose: false }
);
var toast = notify.info("EA-PS2342: starting...", { autoClose: false });

try {
    var i = 0;
    while (i < MAX_READS) {
        if (session.isStopped) break;
        var a1 = qts(await connection.query("MEAS:ALL? 1")).split(",");
        if (session.isStopped) break;
        var a2 = qts(await connection.query("MEAS:ALL? 2")).split(",");
        if (session.isStopped) break;

        function fmtCh(a, n) {
            if (a.length < 4) return "CH"+n+": \u2013\u2013\u2013";
            // a[4] = tracking flag (present in updated bridge)
            var trk = (a.length > 4 && a[4]==="1") ? " \u21d4TRK" : "";
            return "CH"+n+": "
                + parseFloat(a[0]).toFixed(3)+"V  "
                + parseFloat(a[1]).toFixed(4)+"A  "
                + (a[2]==="1" ? "\u25cf\u202fON " : "\u25cb\u202fOFF")
                + " "+a[3]+trk;
        }

        notify.update(toast, {
            render: "["+(i+1)+"]  \u2502  "+fmtCh(a1,1)+"    "+fmtCh(a2,2),
            autoClose: false
        });
        i++;
        await new Promise(r => setTimeout(r, 50));
    }
    notify.dismiss(hint);
    notify.update(toast, { render:"Live stopped after "+i+" reads", autoClose:3000 });
} catch(e) {
    notify.dismiss(hint);
    notify.update(toast, { render:"Live failed: "+e.message, autoClose:5000, type:"error" });
} finally {
    connection.release();
}

