// ── EA-PS2342 CSV Logger ──────────────────────────────────────────────────────
await resetAndAcquire();
try{
    var logRunning = qts(await connection.query("LOG:STATUS?")) === "1";
    if(logRunning){
        var stop = await input({
            title:"EA-PS2342 Logger — Already Running",
            size:"small",
            fields:[{name:"action",displayName:"Action",type:"enum",
                enumItems:[{id:"stop",label:"Stop logging"},{id:"cancel",label:"Cancel"}]}]
        },{action:"stop"});
        if(!stop||stop.action==="cancel"){connection.release();return;}
        connection.command("LOG:STOP");
        await new Promise(r=>setTimeout(r,200));
        notify.info("EA-PS2342 logging stopped.");
        connection.release();
        return;
    }

    var vals = await input({
        title:"EA-PS2342  —  Start CSV Logging",
        size:"medium",
        fields:[
            {name:"filepath",  displayName:"Output file path", type:"string",
             formText:"e.g. C:\\data\\ea_log.csv"},
            {name:"interval",  displayName:"Interval (seconds)", type:"number",
             formText:"Min ~0.15s per channel pair", minValue:0.15},
            {name:"ch1",       displayName:"Log CH1", type:"boolean"},
            {name:"ch2",       displayName:"Log CH2", type:"boolean"},
            {name:"duration",  displayName:"Duration (seconds, 0=manual stop)", type:"number",
             minValue:0}
        ]
    },{filepath:"C:\\data\\ea_log.csv", interval:0.5, ch1:true, ch2:true, duration:0});

    if(!vals){notify.info("Logging cancelled");connection.release();return;}

    var chs = [];
    if(vals.ch1) chs.push("1");
    if(vals.ch2) chs.push("2");
    if(chs.length===0){notify.info("No channels selected");connection.release();return;}

    var dur = vals.duration > 0 ? vals.duration.toString() : "";
    var cmd = "LOG:START "+vals.filepath+","+vals.interval+","+dur+","+chs.join(",");
    connection.command(cmd);
    await new Promise(r=>setTimeout(r,300));
    var status = qts(await connection.query("LOG:STATUS?"));
    if(status==="1"){
        notify.info("Logging started \u2192 "+vals.filepath
            +(vals.duration>0?"  ("+vals.duration+"s)":"  (manual stop)"));
    } else {
        notify.error("Logger did not start — check file path.");
    }
}catch(e){notify.error("Logger failed: "+e.message);}
finally{connection.release();}

